                {s.image && (
                  <div style={{ width: '160px', height: '160px', margin: '0 auto 16px' }}>
                    <img src={s.image} alt={s.title} style={{ width: '100%', height: '100%', objectFit: 'contain', transform: 'scale(2.2)' }} />
