                  </IndustryIconWrap>
                  <IndustryTitle>{ind.name}</IndustryTitle>
                </IndustryCard>
              ))}
            </FocusCards>
          </FocusLayout>
        </Container>
      </Section>

      {/* Divider */}
      <SectionDivider />

      {/* Testimonials */}
      <Section>
        <CanvasTestimonials />
        <Container style={{ position: 'relative', zIndex: 1 }}>
          <SectionHead>
            <EyebrowWrap><EyebrowPill>Reviews</EyebrowPill></EyebrowWrap>
