// Template Component

export const PricingPageTemplate = () => {
  const [isAnnual, setIsAnnual] = useState(false);
  const [selectedPlanIndex, setSelectedPlanIndex] = useState(1);
  const [openFaqIndex, setOpenFaqIndex] = useState<number | null>(null);

  return (
    <Page>
      <HeroSection>
        <PricingHeroCanvas />
        <Container>
          <HeroGlow />
          <EyebrowWrap>
            <EyebrowPill>{pricingHero.eyebrow}</EyebrowPill>
          </EyebrowWrap>
          <H1>{pricingHero.title}<GradientWord>{pricingHero.highlightedTitle}</GradientWord></H1>
          <Body style={{ fontSize: '18px' }}>
            {pricingHero.description}
          </Body>
        </Container>
      </HeroSection>

      <Container>

        <ToggleWrap>
          <ToggleLabelWrap>
            <SaveBadge>{pricingToggles.saveBadge}</SaveBadge>
            <ToggleLabel $active={isAnnual}>{pricingToggles.quarterly}</ToggleLabel>
          </ToggleLabelWrap>
          <SwitchWrapper>
            <input type="checkbox" checked={!isAnnual} onChange={() => setIsAnnual(!isAnnual)} />
            <svg viewBox="0 0 212.4992 84.4688" overflow="visible">
              <defs>
                <linearGradient id="switchGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#3DBF91" />
                  <stop offset="100%" stopColor="#3D4A9B" />
                </linearGradient>
              </defs>
              <path
                pathLength="360"
                fill="none"
                stroke="url(#switchGrad)"
                d="M 42.2496 0 A 42.24 42.24 90 0 0 0 42.2496 A 42.24 42.24 90 0 0 42.2496 84.4688 A 42.24 42.24 90 0 0 84.4992 42.2496 A 42.24 42.24 90 0 0 42.2496 0 A 42.24 42.24 90 0 0 0 42.2496 A 42.24 42.24 90 0 0 42.2496 84.4688 L 170.2496 84.4688 A 42.24 42.24 90 0 0 212.4992 42.2496 A 42.24 42.24 90 0 0 170.2496 0 A 42.24 42.24 90 0 0 128 42.2496 A 42.24 42.24 90 0 0 170.2496 84.4688 A 42.24 42.24 90 0 0 212.4992 42.2496 A 42.24 42.24 90 0 0 170.2496 0 L 42.2496 0"
              ></path>
            </svg>
          </SwitchWrapper>
          <ToggleLabel $active={!isAnnual}>{pricingToggles.monthly}</ToggleLabel>
        </ToggleWrap>

        <GlassRadioWrap>
          <GlassRadioGroup>
            <GlassGlider $index={selectedPlanIndex} />
            <GlassRadioLabel $active={selectedPlanIndex === 0} onClick={() => setSelectedPlanIndex(0)}>
              Launch
            </GlassRadioLabel>
            <GlassRadioLabel $active={selectedPlanIndex === 1} onClick={() => setSelectedPlanIndex(1)}>
              Pro
            </GlassRadioLabel>
            <GlassRadioLabel $active={selectedPlanIndex === 2} onClick={() => setSelectedPlanIndex(2)}>
              Convoa Enterprise
            </GlassRadioLabel>
          </GlassRadioGroup>
        </GlassRadioWrap>

        <PricingContainer>
          <AnimatePresence mode="wait">
            <PlanCard
              key={selectedPlanIndex}
              $popular={pricingPlans[selectedPlanIndex].popular}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              {pricingPlans[selectedPlanIndex].popular && <PopularRibbon>POPULAR</PopularRibbon>}
              <PlanName>{pricingPlans[selectedPlanIndex].name}</PlanName>

              <PlanPriceWrap>
                {pricingPlans[selectedPlanIndex].contactUs ? (
                  <>
                    <PlanPrice $contact>Contact Us</PlanPrice>
                    <PriceSuffix>&nbsp;</PriceSuffix>
                  </>
                ) : (
                  <>
                    <PlanPrice><Currency>$</Currency>{isAnnual ? pricingPlans[selectedPlanIndex].annualPrice : pricingPlans[selectedPlanIndex].monthlyPrice}</PlanPrice>
                    <PriceSuffix>Per Month</PriceSuffix>
                  </>
                )}
              </PlanPriceWrap>

              <FeatureList>
                {pricingPlans[selectedPlanIndex].features.map((feature, i) => (
                  <React.Fragment key={i}>
                    <FeatureItem><CheckIcon /> {feature}</FeatureItem>
                    {i < pricingPlans[selectedPlanIndex].features.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </FeatureList>

              <ActionButton $index={selectedPlanIndex} href="https://app.convoa.ai/login">{pricingPlans[selectedPlanIndex].ctaText}</ActionButton>
            </PlanCard>
          </AnimatePresence>
        </PricingContainer>

        <FaqSection>
          <EyebrowWrap style={{ justifyContent: 'center', marginBottom: '20px' }}>
            <EyebrowPill>FAQ</EyebrowPill>
          </EyebrowWrap>
          <H2 style={{ textAlign: 'center', marginBottom: '48px' }}>Frequently Asked Questions</H2>

          {pricingFaqs.map((faq, index) => (
            <AccordionItem 
              key={index} 
              question={faq.question} 
              isOpen={openFaqIndex === index}
              onToggle={() => setOpenFaqIndex(openFaqIndex === index ? null : index)}
            >
              {faq.image ? (
                <>
                  <p style={{ margin: '0 0 16px 0' }}>{faq.answer}</p>
                  <AppScreenshot>
                    <img src={faq.image} alt={faq.question} />
                  </AppScreenshot>
                </>
              ) : (
                faq.answer
              )}
            </AccordionItem>
          ))}
        </FaqSection>

      </Container>
    </Page>
  );
};
